-- Run once in Supabase SQL Editor. Review before production use.
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','teacher','parent','learner');
create type public.card_status as enum ('draft','for_verification','approved','released');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,full_name text not null,role app_role not null default 'learner',created_at timestamptz default now());
create table public.invitations(id uuid primary key default gen_random_uuid(),email text unique not null,full_name text not null,role app_role not null,created_by uuid references public.profiles(id),used_at timestamptz,created_at timestamptz default now());
create table public.classes(id uuid primary key default gen_random_uuid(),grade_level text not null,section text not null,teacher_id uuid references public.profiles(id),school_year text not null default '2026-2027',unique(grade_level,section,school_year));
create table public.learners(id uuid primary key default gen_random_uuid(),lrn text unique not null,first_name text not null,last_name text not null,birthdate date,class_id uuid references public.classes(id) on delete restrict,parent_user_id uuid references public.profiles(id),learner_user_id uuid references public.profiles(id),status card_status not null default 'draft',released_at timestamptz,parent_acknowledged_at timestamptz,created_at timestamptz default now());
create table public.grades(id uuid primary key default gen_random_uuid(),learner_id uuid references public.learners(id) on delete cascade,learning_area text not null,term1 numeric check(term1 between 0 and 100),term2 numeric check(term2 between 0 and 100),term3 numeric check(term3 between 0 and 100),unique(learner_id,learning_area));
create table public.attendance(id uuid primary key default gen_random_uuid(),learner_id uuid unique references public.learners(id) on delete cascade,term1_days int default 0,term1_present int default 0,term2_days int default 0,term2_present int default 0,term3_days int default 0,term3_present int default 0);
create or replace function public.my_role() returns app_role language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid()$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$declare inv invitations%rowtype; begin select * into inv from invitations where lower(email)=lower(new.email) and used_at is null; if inv.id is null then raise exception 'This email has not been invited by the school administrator'; end if; insert into profiles(id,email,full_name,role) values(new.id,lower(new.email),inv.full_name,inv.role); update invitations set used_at=now() where id=inv.id; return new; end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table profiles enable row level security;alter table invitations enable row level security;alter table classes enable row level security;alter table learners enable row level security;alter table grades enable row level security;alter table attendance enable row level security;
create policy profiles_self_or_admin on profiles for select to authenticated using(id=auth.uid() or my_role()='admin');
create policy admin_profiles on profiles for all to authenticated using(my_role()='admin') with check(my_role()='admin');
create policy admin_invitations on invitations for all to authenticated using(my_role()='admin') with check(my_role()='admin');
create policy classes_visible on classes for select to authenticated using(my_role()='admin' or teacher_id=auth.uid() or my_role() in ('parent','learner'));
create policy admin_classes on classes for all to authenticated using(my_role()='admin') with check(my_role()='admin');
create policy learners_select on learners for select to authenticated using(my_role()='admin' or exists(select 1 from classes c where c.id=class_id and c.teacher_id=auth.uid()) or (parent_user_id=auth.uid() and status='released') or (learner_user_id=auth.uid() and status='released'));
create policy admin_learners on learners for all to authenticated using(my_role()='admin') with check(my_role()='admin');
create policy teacher_update_learners on learners for update to authenticated using(exists(select 1 from classes c where c.id=class_id and c.teacher_id=auth.uid())) with check(exists(select 1 from classes c where c.id=class_id and c.teacher_id=auth.uid()));
create policy linked_user_ack on learners for update to authenticated using(parent_user_id=auth.uid() and status='released') with check(parent_user_id=auth.uid());
create policy grades_select on grades for select to authenticated using(exists(select 1 from learners l left join classes c on c.id=l.class_id where l.id=learner_id and (my_role()='admin' or c.teacher_id=auth.uid() or (l.parent_user_id=auth.uid() and l.status='released') or (l.learner_user_id=auth.uid() and l.status='released'))));
create policy admin_grades on grades for all to authenticated using(my_role()='admin') with check(my_role()='admin');
create policy teacher_grades on grades for all to authenticated using(exists(select 1 from learners l join classes c on c.id=l.class_id where l.id=learner_id and c.teacher_id=auth.uid())) with check(exists(select 1 from learners l join classes c on c.id=l.class_id where l.id=learner_id and c.teacher_id=auth.uid()));
create policy attendance_select on attendance for select to authenticated using(exists(select 1 from learners l left join classes c on c.id=l.class_id where l.id=learner_id and (my_role()='admin' or c.teacher_id=auth.uid() or (l.parent_user_id=auth.uid() and l.status='released') or (l.learner_user_id=auth.uid() and l.status='released'))));
create policy admin_attendance on attendance for all to authenticated using(my_role()='admin') with check(my_role()='admin');
create policy teacher_attendance on attendance for all to authenticated using(exists(select 1 from learners l join classes c on c.id=l.class_id where l.id=learner_id and c.teacher_id=auth.uid())) with check(exists(select 1 from learners l join classes c on c.id=l.class_id where l.id=learner_id and c.teacher_id=auth.uid()));
